create or replace TABLE KFL_PRODUCTION_CLONE_GCP_MIGRATION_20260608_0800.DBP_DATA.BESCH_LIEF_DET_1 cluster by (
      MANDANT_ID,
      DAT_LIEF_SOLL
 )(
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Der Mandant_1 1 steht im DWH für Deutschland (der Wert 22 aus dem SAP System für Deutschland wird in Wert 1 umgewandelt).',
	LIEF_BELEG_ID NUMBER(18,0) NOT NULL COMMENT 'Das Feld enthält die Beleg ID des Lieferscheins und dient der eindeutigen Identifikation der Lieferscheinbelege.',
	LIEF_BELEG_POS_ID NUMBER(18,0) NOT NULL COMMENT 'Das Feld enthält die Nummer einer Lieferscheinposition und dient zusammen mit der Lieferscheinbeleg ID  der eindeutigen Identifikation der Lieferscheinbelegpositionen.',
	KJ NUMBER(38,0) NOT NULL COMMENT 'Kalenderjahr, Format JJJJ',
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Input: Artikel_1 - Id einschliesslich der Generationen - ID (9-stellig); Output: 7stellige L&S-ID + Counter = 8stellige ArtikelID. WWNNNNPC (Warengruppe, Nummer, Prüfziffer, Counter) Regel: Neuer Artikel_1 -> Counter +1',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Mutter Wup_1 ID wird verwendet für Beziehung Lager zu Verteilzentrum',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer',
	MENGE_LIEF_IST_BME NUMBER(18,3) COMMENT 'Menge der Lieferposition, ausgedrückt in Verkaufsmengeneinheiten aus lfimg.',
	VORLAGE_BELEG_ID NUMBER(18,0) NOT NULL COMMENT 'Dieses Feld enthält die Nummer des Vorlagebeleges. (referenzierte Belegart noch unbekannt).',
	VORLAGE_BELEG_POS_ID NUMBER(38,0) NOT NULL COMMENT 'Dieses Feld  enthält die Nummer der Position des Vorlagebeleges. (referenzierte Belegart noch unbekannt)',
	DIFF_ID VARCHAR(1) NOT NULL COLLATE 'en-ci' COMMENT 'Wenn eine_1 Lieferposition nicht vollständig beliefert werden kann, wird die Restmenge vom VZ nachgeliefert oder muss vom Markt neu bestellt werden. Diese Information wird auch als Nachlieferkennzeichen bezeichnet.',
	MENGE_LIEF_SOLL_KOLLI NUMBER(18,3) NOT NULL COMMENT 'Die Soll-Liefermenge dient dazu, die ursprüngliche Liefermenge einer Aus- oder Anlieferung festzuhalten. Sie bezieht sich auf die Mengeneinheit der Liefermenge (LFIMG). Es handelt sich hier um Kolli!  ',
	BRUTTOGEW NUMBER(18,3) NOT NULL COMMENT 'Bruttogesamtgewicht aller Positionen der Lieferung. Das Bruttogewicht setzt sich aus dem Nettogewicht und dem Gewicht der Verpackung zusammen.',
	VERK_MENGE_EINH_ID VARCHAR(3) NOT NULL COLLATE 'en-ci' COMMENT 'Id der alternativen Mengeneinheit. Anhand dieser ID wird pro Mandant_1 und Artikel_1 eine_1 alternative Mengeneinheit eindeutig identifiziert.Aus meinh',
	LAGERORT_ID VARCHAR(4) NOT NULL COLLATE 'en-ci' COMMENT 'Dieses Feld referenziert die DWH Tabelle Lagerort.',
	MENGE_KOLLI NUMBER(18,3) NOT NULL COMMENT 'Dieses Feld enthält die Menge in der Kollimengeneinheit. Der gültige Umrechnungsfaktor wird aus der DWH Tabelle art_umrechnung_faktor_per_1 ermittelt.',
	MENGE_LIEF_PALETTE NUMBER(18,3) COMMENT 'Dieses Feld enthält die Menge in der Palettenmengeneinheit. Der erforderliche Umrechnungsfaktor wird aus den DWH Tabellen art_vorschlagswert_per_1 und art_umrechnung_faktor_per_1 ermittelt.',
	ANNAHMEVERWEIGERUNG_ID NUMBER(38,0) NOT NULL COMMENT 'Dieses Attribut enthält die Gründe für die Annahmeverweigerung. Referenz zu der DWH Tabelle l_annahmeverweigerung_1',
	DAT_HALTBARKEIT DATE COMMENT 'Dieses Feld enthält das Mindesthaltbarkeitsdatum.',
	DAT_AENDERUNG DATE NOT NULL COMMENT 'Dieses Datum stellt das Übernahmedatum bei einem neuen Beleg bzw. das Updatedatum bei einer neuen Version eines Datensatzes dar.',
	BEST_BELEG_ID NUMBER(18,0) NOT NULL COMMENT 'Das Feld enthält die Beleg ID der Bestellung und dient der eindeutigen Identifikation der Bestellbelege. (Dieses Feld hat momentan keine Werte, zukünftig soll dies die Referenz zu der Bestellung ermöglichen)',
	BEST_BELEG_POS_ID NUMBER(38,0) NOT NULL COMMENT 'Das Feld enthält die Nummer einer Bestellposition und dient zusammen mit der Bestellbeleg ID der eindeutigen Identifikation der Bestellpositionen. (Dieses Feld hat momentan keine Werte, zukünftig soll dies die Referenz zu der Bestellung ermöglichen) ',
	DAT_LIEF_SOLL DATE NOT NULL COMMENT 'Datum, bei dem die Lieferung beim Kunden eingehen soll. Das System kann für den Warenausgang das Lieferdatum aufgrund vordefinierter Zeitschätzungen errechnen. Das Feld wird aus der Kopftabelle \""vererbt\"", um einen PPI darüber bilden zu können (Performance',
	MENGE_LIEF_SOLL_BME NUMBER(18,3) COMMENT 'Die Soll-Liefermenge dient dazu, die ursprüngliche Liefermenge einer Aus- oder Anlieferung festzuhalten. Sie ist berechnet (redundante Speicherung) und in Bestellmengeneinheit dargestellt.',
	MENGE_LIEF_IST_KOLLI NUMBER(18,3) COMMENT 'Anzahl der Kollis der Lieferposition. Ermittlung bei der Kommisionierung',
	BETRAG_LIEF_IST NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'redundantes Feld, um den join zur art_gp_wup_zu_per_1 zu sparen, berechnet anzahl_kolli*ek_netto_bnk*komponentenmenge.',
	BETRAG_LIEF_SOLL NUMBER(18,4) WITH MASKING POLICY #unknown_policy COMMENT 'redundantes Feld, um den join zur art_gp_wup_zu_per_1 zu sparen, berechnet menge_lief_soll*ek_netto_bnk*komponentenmenge.',
	MENGE_LIEF_IST_LME NUMBER(18,3) NOT NULL DEFAULT 0 COMMENT 'tatsächlich gelieferte Menge in Lagermengeneinheiten.',
	SYSTEM_ID NUMBER(38,0) NOT NULL DEFAULT 7 COMMENT 'Die System ID kennzeichnet das Quellsystem der Daten (z. B. SAP PR1).',
	AKTIONS_POS_KZ VARCHAR(1) NOT NULL COLLATE 'en-ci' DEFAULT ' ' COMMENT 'Kennzeichen Aktionsposition. Aktionspositionen sind mit X gekennzeichnet. Aus zzlvaktpos',
	BESCH_PALETTE_FG NUMBER(38,0) COMMENT 'Ist gleich 1, wenn die Bestellung in Paletten erfolgte. Denormalisierung von besch_best_det.best_baismenge_einh_id',
	WRG_ID VARCHAR(3) NOT NULL COLLATE 'en-ci' DEFAULT 'EUR' COMMENT 'Kurzbezeichnung der Währung, z.Bsp. CZK, EUR',
	VK_NETTO_LIEF_SOLL NUMBER(18,4) NOT NULL DEFAULT 0 COMMENT 'Liefermenge soll bewertet mit dem Verkaufspreis minus MehrWertSteuer. Redundant abgelegt zur Performancesteigerung',
	VK_NETTO_LIEF_IST NUMBER(18,4) NOT NULL DEFAULT 0 COMMENT 'Liefermenge Ist bewertet mit dem Verkaufspreis minus MehrWertSteuer. Redundant abgelegt zur Performancesteigerung',
	BESTELLART_ID VARCHAR(4) COLLATE 'en-ci' COMMENT 'Durch die Einkaufsbelegart kann man z.B. zwischen einer Bestellung, einer Anfrage und einem Lieferplan unterscheiden.',
	CHARGE_ID VARCHAR(10) COLLATE 'en-ci' COMMENT 'Charge',
	UEBG_CHARGENSPLIT_POS NUMBER(38,0) COMMENT 'Übergeordnete Position der Chargensplitposition',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	MENGE_LIEF_SOLL_ORIG NUMBER(18,3) COMMENT 'Originale Soll-Liefermenge',
	AUSNAHMECODE_MENGENDIFF VARCHAR(4) COMMENT 'Ausnahmecode Lager fuer Mengendifferenz',
	DAT_ART_BEREITSTELLUNG DATE COMMENT 'Artikelbereitstellungsdatum',
	LIEF_POS_TYP_ID VARCHAR(4) COMMENT 'Positionstyp Lieferung'
)COMMENT='TP408 LVS - In dieser Tabelle sind die Belegpositionen der Lieferscheine aus der SAP Tabelle LIPS enthalten - MULTISET. Die dazugehörigen Kopfdaten befinden sich in der DWH Tabelle besch_lief_1 - MULTISET'
;
